// Native Modal error translation is handwritten.
// Classification order: existing SandboxError, abort/timeout DOMException,
// then native Modal types, then unknown. Cause stays on SandboxError.cause.

import { AlreadyExistsError, ClientClosedError, ConflictError, InvalidError, NotFoundError, ResourceExhaustedError, SandboxTimeoutError, TimeoutError } from "modal";
import { ErrorKind, SandboxError, sandboxError, type ErrorInfo } from "@sandbox-kit/sandbox";

export function mapModalError(error: unknown, operation: string): SandboxError {
  if (error instanceof SandboxError) return error;
  if (error instanceof DOMException && error.name === "AbortError") return create(ErrorKind.Canceled, error, operation);
  if (error instanceof DOMException && error.name === "TimeoutError") return create(ErrorKind.Timeout, error, operation);
  let kind: ErrorInfo["kind"] = ErrorKind.Unknown;
  if (kind === ErrorKind.Unknown && error instanceof InvalidError) kind = ErrorKind.InvalidArgument;
  if (kind === ErrorKind.Unknown && error instanceof NotFoundError) kind = ErrorKind.NotFound;
  if (kind === ErrorKind.Unknown && error instanceof AlreadyExistsError) kind = ErrorKind.AlreadyExists;
  if (kind === ErrorKind.Unknown && error instanceof ConflictError) kind = ErrorKind.Conflict;
  if (kind === ErrorKind.Unknown && error instanceof ResourceExhaustedError) kind = ErrorKind.ResourceExhausted;
  if (kind === ErrorKind.Unknown && error instanceof TimeoutError) kind = ErrorKind.Timeout;
  if (kind === ErrorKind.Unknown && error instanceof SandboxTimeoutError) kind = ErrorKind.Timeout;
  if (kind === ErrorKind.Unknown && error instanceof ClientClosedError) kind = ErrorKind.FailedPrecondition;
  return create(kind, error, operation);
}

function create(kind: ErrorInfo["kind"], error: unknown, operation: string, statusCode?: number, providerCode?: string, providerSource?: string): SandboxError {
  return sandboxError({ kind, provider: "modal", operation, field: "", message: error instanceof Error ? error.message : "sandbox-kit modal: provider operation failed", ...(statusCode === undefined ? {} : { statusCode }), ...(providerCode === undefined ? {} : { providerCode }), ...(providerSource === undefined ? {} : { providerSource }) }, error);
}

// Native Daytona error translation is handwritten.
// Classification order: existing SandboxError, abort/timeout DOMException,
// then DaytonaError code/status maps, then unknown. Cause stays on SandboxError.cause.

import { DaytonaError } from "@daytona/sdk";
import { ErrorKind, SandboxError, sandboxError, type ErrorInfo } from "@sandbox-kit/sandbox";

export function mapDaytonaError(error: unknown, operation: string): SandboxError {
  if (error instanceof SandboxError) return error;
  if (error instanceof DOMException && error.name === "AbortError") return create(ErrorKind.Canceled, error, operation);
  if (error instanceof DOMException && error.name === "TimeoutError") return create(ErrorKind.Timeout, error, operation);
  let kind: ErrorInfo["kind"] = ErrorKind.Unknown;
  let statusCode: number | undefined;
  let providerCode: string | undefined;
  let providerSource: string | undefined;
  if (error instanceof DaytonaError) {
    statusCode = error.statusCode;
    providerCode = error.code;
    providerSource = error.source;
    if (kind === ErrorKind.Unknown) switch (error.code) {
      case "SANDBOX_SPOT_EVICTED": kind = ErrorKind.Unavailable; break;
    }
    if (kind === ErrorKind.Unknown) switch (error.statusCode) {
      case 400: kind = ErrorKind.InvalidArgument; break;
      case 401: kind = ErrorKind.Authentication; break;
      case 403: kind = ErrorKind.PermissionDenied; break;
      case 404: kind = ErrorKind.NotFound; break;
      case 408: kind = ErrorKind.Timeout; break;
      case 409: kind = ErrorKind.Conflict; break;
      case 410: kind = ErrorKind.NotFound; break;
      case 412: kind = ErrorKind.FailedPrecondition; break;
      case 422: kind = ErrorKind.InvalidArgument; break;
      case 429: kind = ErrorKind.RateLimited; break;
      case 500: kind = ErrorKind.Internal; break;
      case 502: kind = ErrorKind.Unavailable; break;
      case 503: kind = ErrorKind.Unavailable; break;
      case 504: kind = ErrorKind.Timeout; break;
    }
    if (kind === ErrorKind.Unknown && error.statusCode === 0 && !error.code) kind = ErrorKind.Unavailable;
  }
  return create(kind, error, operation, statusCode, providerCode, providerSource);
}

function create(kind: ErrorInfo["kind"], error: unknown, operation: string, statusCode?: number, providerCode?: string, providerSource?: string): SandboxError {
  return sandboxError({ kind, provider: "daytona", operation, field: "", message: error instanceof Error ? error.message : "sandbox-kit daytona: provider operation failed", ...(statusCode === undefined ? {} : { statusCode }), ...(providerCode === undefined ? {} : { providerCode }), ...(providerSource === undefined ? {} : { providerSource }) }, error);
}

